{
  "interpretation": {
    "name": "TightenVariantFastenersLine2WithSharedNutrunner",
    "scope": {"line": 2, "station": "st2", "tool": "NR7", "variant": "F30"},
    "goal": "Tighten the fasteners of variant F30 at station st2 of line 2 using the shared nutrunner NR7 and record the result.",
    "constraints": [
      "NR7 must be reserved exclusively and its lease renewed before every physical use",
      "NR7 must be transported to st2 by agvexecutor before configure-tool or tighten-fasteners",
      "The tightening program comes only from get-program, with no literal torque values in the Recipe",
      "The tightening result must be recorded for traceability",
      "The reservation must be released after use"
    ],
    "preference": "Minimise cycle time by skipping the quality evaluation, as the operator requested",
    "priority": "normal",
    "horizon": "Single execution for the current request",
    "requested_capabilities": [],
    "omit_services": ["evaluate-tightening"]
  },
  "recipe": {
    "name": "line2-f30-tightening-nr7",
    "first_action": "prepare",
    "actions": [
      {
        "name": "prepare",
        "next": "move-to-station",
        "steps": [
          {
            "name": "reserve-nr7",
            "service": "reserve-tool",
            "next": [],
            "dep": [],
            "executor": null,
            "params": {}
          },
          {
            "name": "fetch-program",
            "service": "get-program",
            "next": [],
            "dep": [],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "move-to-station",
        "next": "tighten",
        "steps": [
          {
            "name": "transport-nr7-to-station",
            "service": "transport-tool",
            "next": [],
            "dep": ["reserve-nr7"],
            "executor": "agvexecutor",
            "params": {"to": "station"}
          }
        ]
      },
      {
        "name": "tighten",
        "next": "record-and-return",
        "steps": [
          {
            "name": "configure-nr7",
            "service": "configure-tool",
            "next": ["tighten-nr7"],
            "dep": ["reserve-nr7", "fetch-program"],
            "executor": null,
            "params": {}
          },
          {
            "name": "tighten-nr7",
            "service": "tighten-fasteners",
            "next": [],
            "dep": ["reserve-nr7", "configure-nr7"],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "record-and-return",
        "next": "finish",
        "steps": [
          {
            "name": "record-result",
            "service": "record-tightening",
            "next": [],
            "dep": ["tighten-nr7"],
            "executor": null,
            "params": {}
          },
          {
            "name": "transport-nr7-to-crib",
            "service": "transport-tool",
            "next": [],
            "dep": ["reserve-nr7"],
            "executor": "agvexecutor",
            "params": {"to": "crib"}
          }
        ]
      },
      {
        "name": "finish",
        "next": null,
        "steps": [
          {
            "name": "release-nr7",
            "service": "release-tool",
            "next": [],
            "dep": ["reserve-nr7"],
            "executor": null,
            "params": {}
          }
        ]
      }
    ]
  }
}
